let bg = "#0393FF";

function setup(){
  createCanvas(900, 600);
  background(bg);
}

function draw(){
  background(bg);
  noStroke();  

  let step = 60;
  for(let x = step; x < width-step; x+= step){
    for(let y = step; y < height-step; y+= step){  
      tri(x, y);
    }
  }

  // noLoop() removed for animation
}

function tri(x, y){
  let t = random(1);
  let c = random(1);

  if(c < 0.5){
    fill(0);
  } else {
    fill(255);
  }

  pushMatrix();

  translate(x, y);
  if(t < 0.5){
    triangle(0, 0, 60, 0, 30, 60);
  } else {
    triangle(0, 60, 30, 0, 60, 60);
  }

  popMatrix();
}

function mousePressed(){
  redraw();
}
